const ARTICLES = [
  {"id":1, "cat":"delhii", "title":"COP31 хэлэлцээ нурж, 200 шахам улс уур амьсгалын гэрээнд хүрч чадсангүй", "titleEn":"COP31 talks collapse as nearly 200 countries fail to agree on climate deal", "time":"15 мин", "timeEn":"15 min", "img":"https://commons.wikimedia.org/wiki/Special:FilePath/Antalya%2C%20Turkey%20-%20panoramio%20%281%29.jpg?width=1000", "text":"Туркийн Анталья хотноо хоёр долоо хоног үргэлжилсэн НҮБ-ын уур амьсгалын өөрчлөлтийн бага хурал буюу COP31 ням гарагт нэгдсэн гэрээнд хүрч чадалгүй өндөрлөлөө. 190 гаруй орны төлөөлөгчид чулуужсан түлшний талаарх заалт дээр санал зөрөлдөж, эцсийн баримт бичгийг батлах нэгдсэн ойлголцолд хүрсэнгүй. Хэлэлцээ албан ёсны төгсгөлөөсөө 44 цагаар хэтэрч, түүхэн дэх хамгийн удаан үргэлжилсэн COP болсон бөгөөд 2009 оны Копенгагены хурлаас хойш анх удаа ийнхүү нэгдсэн гэрээгүй дуусч байна.\n\nМаргааны гол сэдэв нь чулуужсан түлш байв. Эхний төсөлд «чулуужсан түлшнээс эрчим хүчний системд нэн даруй шилжих» тухай заалт байсан ч дараагийн бүх төслөөс чулуужсан түлшний талаарх дурдлага хасагдсан юм. 100 гаруй улс уг заалтыг хадгалахыг шаардаж байсан ч Саудын Араб тэргүүтэй газрын тос олборлогч орнууд эсэргүүцжээ. Европын Холбоо, Панам, Маршаллын арлууд, Норвеги эцсийн төслийг хүлээн авахаас татгалзсан байна.\n\nЕвропын Холбоог төлөөлөн хэлэлцээнд оролцсон Ирландын уур амьсгалын сайд Дарраг О'Брайен «чулуужсан түлшийг огт дурдаагүй гэрээг дэмжихгүй» гэж мэдэгдлээ. COP31-ийн дарга, Туркийн сайд Мурат Курум «бид чадах бүхнээ хийлээ, гэхдээ энэ баримт бичигт зөвшилцөл алга» гэж хүлээн зөвшөөрсөн юм. Уур амьсгалын шинжээчид гэрээгүй дуусах нь «гэрээгүй байх нь бүтэлгүй гэрээнээс дээр» гэж үзэж байгаа бол байгаль орчны байгууллагууд үүнийг сэрэмжлүүлэг гэж нэрлэж байна.\n\nХэлэлцээний үеэр жижиг асуудлуудаар ахиц гарсан байна. Тухайлбал, дасан зохицох санхүүжилтийг 2035 он гэхэд гурав дахин нэмэгдүүлэхээр тохирсон ч ямар суурь үзүүлэлтээс тоолох нь тодорхойгүй үлджээ. Ирэх жилийн уур амьсгалын дээд хэмжээний уулзалт 2027 оны арваннэгдүгээр сард Этиопын нийслэл Аддис-Абебад болно.", "textEn":"The UN climate conference COP31 in Antalya, Turkey, ended on Sunday without an overarching agreement after two weeks of talks. Delegates from more than 190 countries failed to reach consensus, divided over language on fossil fuels. The talks ran more than 44 hours into overtime, making it the longest COP on record, and the first to end without an agreed deal since Copenhagen in 2009.\n\nFossil fuels were the central dispute. The first draft called for an 'immediate transition away from fossil fuels in energy systems', but every mention was stripped from later drafts. More than 100 countries pushed to keep the language, while Saudi Arabia and other oil-producing states resisted. The European Union, Panama, the Marshall Islands and Norway rejected the final text.\n\nIreland's climate minister Darragh O'Brien, speaking for the EU, said the bloc would not endorse a deal 'that does not even mention fossil fuels'. COP31 president Murat Kurum of Turkey admitted 'we have done our utmost', but 'there is no consensus on this document'. Climate experts said no deal was better than a bad deal, while environmental groups called the collapse a wake-up call.\n\nSome progress was made on smaller issues. Delegates agreed to triple adaptation finance by 2035, though the baseline was left unclear. Next year's climate summit will be held in Addis Ababa, Ethiopia, in November 2027."},
  {"id":2, "cat":"uls-tor", "title":"У.Хүрэлсүх: Ерөнхийлөгчийн сонгуулийн хамт Үндсэн хуулийн өөрчлөлтийн санал асуулга явуулья", "titleEn":"Khurelsukh calls for constitutional referendum alongside presidential election", "time":"30 мин", "timeEn":"30 min", "img":"https://commons.wikimedia.org/wiki/Special:FilePath/2024-10-18%20Ulaanbaatar%2C%20Government%20Palace.jpg?width=760", "text":"Ерөнхийлөгчийн албан тушаалаас чөлөөлөгдөх хүсэлтээ гаргасан У.Хүрэлсүх албан тушаалаасаа буухаасаа өмнө удахгүй болох Ерөнхийлөгчийн сонгуулийн хамт Үндсэн хуульд өөрчлөлт оруулах тухай бүх нийтийн санал асуулга явуулахыг уриаллаа. Тэрбээр хоёр танхимтай парламент байгуулж, Ерөнхийлөгчийг парламентаас сонгодог болох, эсвэл Ерөнхийлөгчийн засаглалд шилжин гүйцэтгэх засаглалын эрхийг нэмэгдүүлэх гэсэн хоёр хувилбарыг санал болгосон байна.\n\nУИХ санал асуулга явуулах талаар хараахан шийдвэр гаргаагүй байна. Үндсэн хуулийн дагуу Ерөнхийлөгчийн ээлжит бус сонгуулийг дөрвөн сарын дотор зарлан явуулах ёстой бөгөөд сонгуулийн товыг суудал чөлөөлөгдсөнөөс хойш ажлын 20 хоногийн дотор зарлаж, санал хураалтыг зарласнаас хойш дор хаяж 70 хоногийн дараа товлоно. Ингэснээр шинэ Ерөнхийлөгчийг 2027 оны гуравдугаар сард сонгох боломжтой гэж үзэж байна.\n\nУ.Хүрэлсүх арваннэгдүгээр сарын 17-нд өөрийн хүсэлтээр чөлөөлөгдөх өргөдлөө өгч, УИХ арваннэгдүгээр сарын 19-нд хуралдаанд оролцсон 104 гишүүний 96 буюу 92.3 хувийн саналаар дэмжсэн юм. Энэ нь Монгол Улсын түүхэнд Ерөнхийлөгч бүрэн эрхийн хугацаа дуусахаас өмнө албан тушаалаасаа чөлөөлөгдсөн анхны тохиолдол болж байна. Тэрбээр өөрийгөө хэзээ ч худал хэлж, хулгай хийж, бусдыг хуурч байгаагүй гэж мэдэгдэж, буруутгалыг эрс няцааж байгаа юм.\n\nТүүнийг нийслэлийн Засаг дарга асан Х.Нямбаатар «Боди Интернэшнл» компанийн Тавантолгой-Гашуунсухайт төмөр замын гэрээтэй холбогдуулан 110 орчим сая ам.долларын авлига төлсөн, үүнээс 25 сая ам.доллар нь Ерөнхийлөгчид очсон гэж буруутгасан билээ. Одоогоор УИХ-ын дарга С.Бямбацогт Ерөнхийлөгчийн үүргийг түр хэрэгжүүлж байгаа бөгөөд сонгогдсон шинэ Ерөнхийлөгч зургаан жилийн хугацаатай, нэг удаагийн бүрэн эрхтэй ажиллах юм.", "textEn":"Outgoing President U. Khurelsukh has called for a constitutional referendum to be held alongside the coming presidential election, before leaving office. He proposed two options: creating a bicameral parliament that would elect the president, or shifting to a presidential system with greater executive powers.\n\nParliament has yet to decide on a referendum. Under the Constitution, an extraordinary presidential election must be held within four months, with the date announced within 20 working days of the vacancy and polling day at least 70 days after the announcement. That would allow the new President to be elected in March 2027.\n\nKhurelsukh submitted his request to be relieved of office at his own request on November 17, and Parliament backed it on November 19 with 96 of the 104 members present — 92.3 percent — voting in favour. It is the first time in Mongolia's history that a President has left office before the end of his term. He says he has never lied, stolen or deceived anyone, and strongly denies the allegations.\n\nFormer Ulaanbaatar mayor Kh. Nyambaatar accused him of involvement in around 110 million US dollars in bribes linked to the Tavantolgoi-Gashuunsukhait railway contract awarded to Bodi International, of which 25 million dollars allegedly went to the President. Parliament Speaker S. Byambatsogt is now exercising presidential powers, and the newly elected President will serve a single six-year term."},
  {"id":3, "cat":"ediin-zasag", "title":"Оюутолгойн ашгаас иргэн бүрд 857 мянган төгрөг олгох асуудлыг судлах ажлын хэсэг байгууллаа", "titleEn":"Parliament forms working group on paying Oyu Tolgoi dividends of 857,000 tugrik to each citizen", "time":"45 мин", "timeEn":"45 min", "img":"https://commons.wikimedia.org/wiki/Special:FilePath/Oyu%20Tolgoi%2007.JPG?width=760", "text":"УИХ-ын Өргөдлийн байнгын хороо Оюутолгойн ашгаас иргэн бүрд 857,000 төгрөгийг хувь дансанд нь бэлнээр шилжүүлэх тухай хуулийн төсөл санаачлах асуудлыг судлах ажлын хэсэг байгууллаа. Ажлын хэсэгт УИХ-ын гишүүн Н.Батсүмбэрэл, Б.Жавхлан, Б.Заяабал, О.Номинчимэг, Ц.Баатархүү, С.Замира, Б.Бат-Эрдэнэ, Г.Лувсанжамц, П.Батчимэг нар багтсан байна.\n\nИргэн Х.Оюунбилэг аравдугаар сарын 23-нд Оюутолгойн ногдол ашгийг иргэдийн дансанд өгөх агуулгатай нийтийн өргөдөл санаачилж, 100,000 санал авсан юм. Өргөдөлд дурдсанаар Оюу толгойн ордыг 30 жил ашигласны эцэст Монгол Улс анх удаагаа 3 их наяд төгрөгийн ашиг авахаар болсон бөгөөд нийт 3.5 сая иргэндээ хуваавал нэг иргэнд 857,000 төгрөг оногдож байгаа ажээ. Уг 3 их наяд төгрөгийн ногдол ашиг 2027 онд улсын төсөвт шилжих төлөвтэй байна.\n\nӨргөдлийн болон Эдийн засгийн байнгын хорооны хамтарсан хуралдаанд оролцсон гишүүдийн олонх ажлын хэсэг байгуулах саналыг дэмжсэн байна. Ажлын хэсэг ногдол ашгийг хэрхэн хуваарилах талаар санал, зөвлөмж боловсруулж, УИХ-д танилцуулах юм.\n\nГэхдээ Засгийн газар уг саналыг дэмжихгүй байгаагаа өмнө нь илэрхийлсэн билээ. Сангийн сайд З.Мэндсайхан арваннэгдүгээр сарын 4-нд Ерөнхийлөгч У.Хүрэлсүхийн Оюутолгойн ногдол ашгийг бэлнээр олгох саналыг Засгийн газар хүлээн авахгүй гэж мэдэгдсэн юм. Иймд ажлын хэсгийн дүгнэлт, УИХ-ын шийдвэр цаашид анхаарал татаж байна.", "textEn":"Parliament's Standing Committee on Petitions has formed a working group to study a proposal to pay 857,000 tugrik from Oyu Tolgoi profits in cash into each citizen's personal account. The group includes MPs N. Batsumberel, B. Javkhlan, B. Zayabal, O. Nominchimeg, Ts. Baatarkhuu, S. Zamira, B. Bat-Erdene, G. Luvsanjamts and P. Batchimeg.\n\nCitizen Kh. Oyunbileg launched a public petition on October 23 calling for the Oyu Tolgoi dividend to be paid to citizens, gathering 100,000 signatures. According to the petition, after 30 years of operating the Oyu Tolgoi deposit, Mongolia is set to receive 3 trillion tugrik in profit for the first time, which would give 857,000 tugrik to each of the country's 3.5 million citizens. The 3 trillion tugrik dividend is expected to be transferred to the state budget in 2027.\n\nMost members at a joint session of the Petitions and Economy standing committees backed forming the working group. It will prepare proposals and recommendations on how to allocate the dividend and present them to Parliament.\n\nThe government, however, has already signalled it does not support the idea. Finance Minister Z. Mendsaikhan said on November 4 that the government would not accept then-President U. Khurelsukh's proposal to pay the Oyu Tolgoi dividend in cash. The working group's conclusions and Parliament's decision are therefore being closely watched."},
  {"id":4, "cat":"uls-tor", "title":"2027 оны Ерөнхийлөгчийн сонгуулийн судалгаагаар хоёр Ерөнхий сайд асан тэргүүлж байна", "titleEn":"Two former prime ministers lead the field in 2027 presidential race poll", "time":"1 цаг", "timeEn":"1 hour", "img":"https://commons.wikimedia.org/wiki/Special:FilePath/2024-10-18%20Ulaanbaatar%2C%20S%C3%BCkhbaatar%20Square.jpg?width=760", "text":"2027 оны Ерөнхийлөгчийн ээлжит бус сонгуулийн өмнөх саяхны олон нийтийн судалгаагаар Ерөнхий сайд асан хоёр улстөрч тэргүүлж байгаа ажээ. Монгол Ардын Намаас Ерөнхий сайд асан Г.Занданшатар, Ардчилсан Намаас Ерөнхий сайд асан Н.Алтанхуяг нар судалгаагаар тэнцүү байр суурь эзэлж, өрсөлдөгчдөөсөө хол тасарсан байна.\n\nХэвлэлд МАН-аас Ерөнхий сайд асан Я.Содбаатарын нэр мөн нэр дэвшигчийн хувиар дурдагдаж байгаа бол Ардчилсан намаас хэд хэдэн улстөрч намын сунгаанд оролцох сонирхлоо илэрхийлээд байна. Сонгууль 2027 оны гуравдугаар сард болох төлөвтэй байгаа бөгөөд ялагч нь зургаан жилийн хугацаатай, нэг удаагийн бүрэн эрхтэй Ерөнхийлөгчөөр ажиллах юм.\n\nСудалгаагаар тэргүүлэгч хоёр нэр дэвшигч тус бүр өөрийн гэсэн давуу болон сул талтай гэж шинжээчид үзэж байна. Г.Занданшатар 2026 оны гуравдугаар сард Ерөнхий сайдын албан тушаалаасаа огцорсон бол Н.Алтанхуяг өмнө нь Ерөнхий сайд болон УИХ-ын гишүүнээр ажиллаж байсан туршлагатай улстөрч юм.\n\nМонгол Улс сүүлийн жилүүдэд улс төрийн тогтворгүй байдалтай тулгарч байна. 2025 оны зургадугаар сард Ерөнхий сайд асан Л.Оюун-Эрдэнэ огцорч, 2026 оны гуравдугаар сард түүний залгамжлагч Г.Занданшатар мөн албан тушаалаасаа буусан билээ. Ийм нөхцөлд ээлжит бус Ерөнхийлөгчийн сонгууль улс орны улс төрийн ирээдүйд шийдвэрлэх ач холбогдолтой гэж ажиглагчид үзэж байна.", "textEn":"A recent public survey puts two former prime ministers level at the top of the field for Mongolia's 2027 extraordinary presidential election. Former Prime Minister G. Zandanshatar of the Mongolian People's Party and former Prime Minister N. Altankhuyag of the Democratic Party are tied at the top of the poll, well ahead of other potential candidates.\n\nMedia reports have also mentioned former Prime Minister Ya. Sodbaatar as a possible candidate from the MPP, while several Democratic Party politicians have expressed interest in their party's primary. The election is expected in March 2027, and the winner will serve a single six-year term as President.\n\nAnalysts say each of the two frontrunners carries his own strengths and weaknesses. Zandanshatar resigned as Prime Minister in March 2026, while Altankhuyag is an experienced politician who has served as Prime Minister and as a member of Parliament.\n\nMongolia has faced political instability in recent years. Former Prime Minister L. Oyun-Erdene resigned in June 2025, and his successor Zandanshatar also stepped down in March 2026. Observers say the snap presidential election will therefore be decisive for the country's political future."},
  {"id":5, "cat":"ediin-zasag", "title":"Засгийн газар АИ-92 шатахууны үнийг бууруулж, Евро-5 руу шилжих асуудлыг хэлэлцэж байна", "titleEn":"Government cuts AI-92 fuel prices and weighs shift to Euro-5 petrol", "time":"1 цаг", "timeEn":"1 hour", "img":"https://commons.wikimedia.org/wiki/Special:FilePath/Ingo%20petrol%20station%20F%C3%A5r%C3%B6sund%20July%2001.jpg?width=760", "text":"Засгийн газар АИ-92 шатахууны үнийг бууруулахаар шийдвэрлэж, Евро-5 стандартын шатахууны үнийг бууруулах болон АИ-92-г үе шаттайгаар халах асуудлыг хэлэлцэж байна. Энэ нь шатахууны үнэ, чанарын талаарх бодлогын шинэ алхам болж байна.\n\nМонгол Улс шатахуунаа бараг бүхэлд нь Оросоос импортолдог бөгөөд үнийн өөрчлөлт нь иргэдийн амьжиргаа, тээврийн зардалд шууд нөлөөлдөг. АИ-92 нь Монголд хамгийн өргөн хэрэглэгддэг шатахууны төрөл боловч чанарын хувьд Евро-5 стандартаас доогуур гэж үздэг. Евро-5 руу шилжих нь агаарын бохирдлыг бууруулахад хувь нэмэр оруулах төлөвтэй байна.\n\nШатахууны үнийг бууруулах шийдвэр нь Ерөнхийлөгч У.Хүрэлсүх албан тушаалаасаа чөлөөлөгдсөнтэй зэрэгцэн гарч байгаа бөгөөд Засгийн газар иргэдийн амьжиргааг дэмжих арга хэмжээ авч байгаагийн нэг хэсэг гэж үзэж болно. Төсвийн тодотгол, 2027 оны төсөв батлагдсантай холбогдуулан эдийн засгийн бодлогын шийдвэрүүд дараалан гарч байна.\n\nАИ-92-г халах нь шатахуун түгээх станцууд, автомашин эзэмшигчдэд шилжилтийн хугацаа шаардах бөгөөд Засгийн газар уг шилжилтийг хэрхэн зохион байгуулах талаар дэлгэрэнгүй төлөвлөгөө боловсруулж байгаа юм. Иргэд шатахууны үнийн өөрчлөлтийг ойрын өдрүүдэд мэдрэх төлөвтэй байна.", "textEn":"The government has decided to cut the price of AI-92 petrol and is considering lowering the price of Euro-5 petrol and phasing out AI-92 altogether. The move is a new step in fuel price and quality policy.\n\nMongolia imports almost all of its fuel from Russia, and price changes directly affect people's living costs and transport expenses. AI-92 is the most widely used petrol in Mongolia, but it is regarded as lower quality than the Euro-5 standard. A shift to Euro-5 is expected to help reduce air pollution.\n\nThe price cut comes as President U. Khurelsukh leaves office, and can be seen as part of government measures to support people's livelihoods. Economic policy decisions have followed one after another since the approval of the 2027 budget.\n\nPhasing out AI-92 will require a transition period for filling stations and vehicle owners, and the government is working on a detailed plan for the change. Consumers are expected to feel the price change in the coming days."},
  {"id":6, "cat":"ediin-zasag", "title":"Хятад-Монгол-Оросын олон улсын зорчигч тээврийн галт тэрэг арваннэгдүгээр сарын 25-наас явж эхэлнэ", "titleEn":"China-Mongolia-Russia international passenger train to start on November 25", "time":"1 цаг", "timeEn":"1 hour", "img":"https://commons.wikimedia.org/wiki/Special:FilePath/UBTZ%202TE116UM-022%20Cagaan%20Had%20-%20Sumangijn%20Zoo.jpg?width=760", "text":"Хятад, Монгол, Оросын гурван улсыг холбосон олон улсын зорчигч тээврийн галт тэрэгний үйлчилгээ арваннэгдүгээр сарын 25-наас эхэлж, долоо хоногт нэг удаа хоёр чиглэлд явах гэж байна. Энэ тухай Хятадын Төмөр замын групп мэдээлжээ.\n\nШинэ чиглэл нь гурван улсын хоорондын зорчигч тээвэр, аялал жуулчлал, худалдааг дэмжих зорилготой. Монгол Улс газар зүйн байрлалынхаа хувьд Хятад, Оросыг холбосон дамжин өнгөрөх тээврийн чухал зангилаа бөгөөд төмөр замын зорчигч тээвэр сэргэх нь бүс нутгийн хамтын ажиллагааг бэхжүүлэхэд хувь нэмэр оруулна гэж үзэж байна.\n\nМонгол Улс сүүлийн жилүүдэд агаарын тээврийн чиглэл, визний хөнгөлөлтийг өргөжүүлж, гадаадын жуулчдыг татах чиглэлээр ажиллаж байгаа юм. Энэ оны арваннэгдүгээр сарын 15-ны байдлаар Монголд 958,470 гадаадын жуулчин ирсэн нь нэг сая жуулчин хүлээн авах зорилтод дөхөж байгааг харуулж байна. Төмөр замын шинэ чиглэл нь жуулчдын урсгалыг нэмэгдүүлэх боломжтой.\n\nГалт тэрэгний хуваарь, тасалбарын үнэ, зорчих журмын талаарх дэлгэрэнгүй мэдээллийг төмөр замын байгууллагууд ойрын өдрүүдэд зарлах төлөвтэй байна. Гурван улсын төмөр замын байгууллагууд хамтран ажиллаж, зорчигчдод тав тухтай үйлчилгээ үзүүлэхээр бэлтгэж байгаа ажээ.", "textEn":"A new international passenger train service linking China, Mongolia and Russia will start on November 25, running once a week in both directions, China State Railway Group has announced.\n\nThe new service aims to support passenger transport, tourism and trade between the three countries. Mongolia's geographic position makes it an important transit hub between China and Russia, and the revival of cross-border rail passenger services is expected to strengthen regional cooperation.\n\nMongolia has been expanding air routes and visa exemptions in recent years to attract foreign visitors. As of November 15 this year, 958,470 foreign tourists had arrived in Mongolia, bringing the country close to its goal of welcoming one million visitors. The new rail service could add to that flow.\n\nRailway authorities are expected to announce timetables, ticket prices and travel procedures in the coming days. The railway organisations of the three countries are working together to provide comfortable services for passengers."},
  {"id":7, "cat":"niigem", "title":"Өвлийн элсэлтийн шалгалтын бүртгэл өнөөдөр 18:00 цагт хаагдана", "titleEn":"Winter university entrance exam registration closes today at 18:00", "time":"45 мин", "timeEn":"45 min", "img":"https://commons.wikimedia.org/wiki/Special:FilePath/Students%20writing%20in%20class.jpg?width=760", "text":"2026 оны өвлийн монгол хэл бичгийн болон элсэлтийн шалгалтын бүртгэл өнөөдөр буюу арваннэгдүгээр сарын 23-ны 18:00 цагт дуусна. Бүртгэл eyesh.eec.mn цахим хуудсаар явагдаж байгаа бөгөөд бүртгэлийн хугацааг сунгахгүй гэж Боловсролын үнэлгээний төвөөс мэдээлсэн байна.\n\nШалгуулагчид бүртгүүлэхдээ зөвхөн өөрийн и-мэйл хаягийг ашиглах ёстой бөгөөд нэг хичээлийн хураамж 20,000 төгрөг байна. Шалгалт өгөх хичээлээ сонгож, хураамжаа бүртгэлийн хугацаанд төлсөн байх шаардлагатай. Түүх, нийгэм судлал зэрэг хичээлээс хоёроос дээшийг сонгож бүртгүүлэх боломжтой.\n\nӨвлийн элсэлтийн шалгалт нь их, дээд сургуульд элсэн орохыг хүсэгчдэд жилд хоёр дахь боломжийг олгодог бөгөөд ялангуяа шалгалтандаа бэлтгэж амжаагүй, эсвэл дүнгээ сайжруулахыг хүссэн сурагчдад чухал ач холбогдолтой. Мөн монгол хэл бичгийн шалгалт нь их сургуульд элсэхэд тавигддаг шалгуурын нэг юм.\n\nБүртгэлийн хугацаа дуусахаас өмнө бүртгүүлж амжаагүй шалгуулагчид дараагийн шалгалтыг хүлээх шаардлагатай болно. Тиймээс шалгалт өгөхөөр төлөвлөж буй иргэдийг өнөөдөр 18:00 цагаас өмнө бүртгэлээ баталгаажуулахыг Боловсролын үнэлгээний төвөөс анхааруулж байна.", "textEn":"Registration for the 2026 winter Mongolian language and university entrance examinations closes today, November 23, at 18:00. Registration is open at eyesh.eec.mn, and the Education Evaluation Centre says the deadline will not be extended.\n\nCandidates must register using their own email address, and the fee is 20,000 tugrik per subject. They must select the subjects they will sit and pay the fee within the registration period. Two or more subjects can be chosen from options including history and social studies.\n\nThe winter entrance examination gives applicants a second chance each year to enter university, and it matters particularly for students who need more preparation time or want to improve their scores. The Mongolian language test is also one of the requirements for university admission.\n\nCandidates who do not register before the deadline will have to wait for the next examination. The Education Evaluation Centre is therefore urging anyone planning to sit the exams to confirm their registration before 18:00 today."},
  {"id":8, "cat":"niigem", "title":"Орон сууц захиалсан 500 иргэн байрандаа орж чадалгүй долоон жил болжээ", "titleEn":"500 citizens wait seven years for apartments they ordered", "time":"1 цаг", "timeEn":"1 hour", "img":"https://commons.wikimedia.org/wiki/Special:FilePath/Ulaanbaatar%20new%20buildings%20in%20Yaarmag.jpg?width=760", "text":"Хан-Уул дүүргийн 21 дүгээр хороонд байрлах «Ю-Апартмент» хотхоны захиалагчид болох 500 иргэн байрандаа орж чадалгүй долоон жил болж байгаа талаар өнөөдөр мэдээлэл хийнэ. Тэд Яармагийн шинэ хотын захиргааны үүдэнд 11:00 цагт цугларч, нөхцөл байдлынхаа талаар олон нийтэд мэдээлэхээр төлөвлөж байна.\n\nХотхоныг «Юникл таувер» компани барьж байгаа бөгөөд захиалагчид орон сууцаа захиалж, төлбөрөө төлсөн ч байрандаа орж чадаагүй байна. Долоон жилийн хугацаанд иргэд түрээсийн байранд амьдрах, эсвэл хамаатныдаа байрлах зэргээр хүндрэлтэй нөхцөлд байгаа ажээ.\n\nОрон сууцны захиалгатай холбоотой маргаан Монголд олон жил үргэлжилж байгаа асуудал бөгөөд барилгын компаниуд хугацаандаа хүлээлгэн өгөхгүй байх, санхүүгийн хүндрэлд орох зэрэг шалтгаанаар иргэд хохирдог. Зарим тохиолдолд иргэд шүүхэд хандаж, эрхээ хамгаалуулахаас өөр аргагүй болдог.\n\nЭнэ удаагийн мэдээллээр иргэд асуудлыг шийдвэрлэхийн тулд холбогдох байгууллагуудад хандаж, анхаарал хандуулахыг хүсч байгаа юм. Хотхоны захиалагчдын асуудлыг шийдвэрлэхэд барилгын компанийн санхүүжилт, зөвшөөрлийн асуудал, төрийн байгууллагуудын хяналт чухал үүрэгтэй гэж үзэж байна.", "textEn":"Five hundred citizens who ordered apartments in the Yu-Apartment complex in the 21st khoroo of Khan-Uul district say they have been unable to move into their homes for seven years. They plan to brief the public today at 11:00 outside the Yarmag new city administration building.\n\nThe complex is being built by Unicl Tower LLC, and although the buyers ordered and paid for their apartments, they still cannot move in. Over seven years, residents have had to live in rented flats or stay with relatives.\n\nDisputes over ordered apartments have been a long-running problem in Mongolia, with buyers suffering when construction companies miss deadlines or run into financial trouble. In some cases citizens have no option but to go to court to protect their rights.\n\nWith today's briefing, the buyers want the relevant authorities to pay attention and help resolve the matter. Resolving it will depend on the developer's financing, permits and oversight by state bodies, observers say."},
  {"id":9, "cat":"niigem", "title":"Угаарын хийн дуудлагаар нэг шөнөдөө 98 өрхийн 294 иргэнийг аварчээ", "titleEn":"294 people in 98 households saved from carbon monoxide in one night", "time":"1 цаг", "timeEn":"1 hour", "img":"https://commons.wikimedia.org/wiki/Special:FilePath/Ger%20District%20Panorama%20%286141857498%29.jpg?width=760", "text":"Нийслэлд арваннэгдүгээр сарын 19-20-нд шилжих шөнө нийт 98 өрхөөс угаарын хийн дуудлага ирж, 294 иргэнийг болзошгүй эрсдэлээс урьдчилан сэргийлжээ. Үүнээс 32 өрх утсаа аваагүй тул гэрээт хяналтын ажилтнууд гэрт нь очиж ажилласан байна. Энэ тухай Түлш хэрэглэгчдэд үйлчлэх төвөөс мэдээллээ.\n\nУгаар мэдрэгч дохио өгсөн айлуудад ажилтнууд шуурхай очиж, зуух пийшингийн битүүмж, түлшний хэрэглээг шалгаж, зөвлөгөө өгч ажилласан байна. Иргэд шилжилт хөдөлгөөн хийсэн бол харьяа хороонд өрхийн бүртгэлээ яаралтай хийлгэж, 7011-9410 дугаарт холбогдон алсын зайн дамжуулагчтай угаар мэдрэгч суурилуулахыг тус төвөөс сануулжээ.\n\nТүүнчлэн согтууруулах ундааг тохируулан хэрэглэж, өөрийгөө болон гэр бүлээ угаартах эрсдэлд оруулахгүй байхыг бодит тохиолдлоос үндэслэн онцгойлон сэрэмжлүүлсэн байна. Арваннэгдүгээр сарын 17-ны 17:30 цагийн орчимд Баянзүрх дүүргийн нэгэн айлаас угаарын хий өссөн дуудлага бүртгэгдэж, ажилтан гэрт нь очиход тус иргэн согтууруулах ундаа хэтрүүлэн хэрэглэсэн байдалтай, зуух пийшингийн битүүмж алдагдаж, түлш хэтрүүлэн чихэж, пийшингийн тагийг нээсэн байжээ.\n\nУгаарын хий нь үнэргүй, өнгөгүй тул хордлогод орж, амь насаараа хохирох аюултай. Толгой өвдөх, дотор муухайрах, сульдах зэрэг шинж тэмдэг илэрвэл даруй цэвэр агаарт гарч, яаралтай тусламж дуудах шаардлагатай гэж мэргэжилтнүүд анхааруулж байна. Өвлийн улиралд гэр хорооллын айл өрхүүд нүүрс түлж халаадаг нь угаартах эрсдэлийг нэмэгдүүлдэг юм.", "textEn":"In Ulaanbaatar, 98 households called about carbon monoxide on the night of November 19-20, and 294 people were saved from possible danger, the Fuel Consumers Service Centre said. Thirty-two households did not answer their phones, so contracted inspectors visited their homes.\n\nInspectors rushed to homes where carbon monoxide detectors had sounded, checking stove seals and fuel use and giving advice. The centre urged residents who have moved to register their household with their local khoroo promptly and to call 7011-9410 to have a carbon monoxide detector with a remote transmitter installed.\n\nIt also warned people to drink alcohol in moderation and not to put themselves or their families at risk of carbon monoxide poisoning, citing a real case. At around 17:30 on November 17, a call about rising carbon monoxide came from a household in Bayanzurkh district; when an inspector arrived, the resident was heavily intoxicated, the stove seal was broken, the stove was overfilled with fuel and its lid was open.\n\nCarbon monoxide is odourless and colourless, so poisoning can be fatal. Experts warn that headaches, nausea or weakness mean getting into fresh air at once and calling emergency services. In winter, ger district households heat with coal, which increases the risk of poisoning."},
  {"id":10, "cat":"delhii", "title":"Ардчилсан нам АНУ-ын Төлөөлөгчдийн танхимд 258 суудал авч, 1992 оноос хойших хамгийн том ялалтаа байгууллаа", "titleEn":"Democrats clinch 258 House seats, their largest majority since 1992", "time":"30 мин", "timeEn":"30 min", "img":"https://commons.wikimedia.org/wiki/Special:FilePath/Capitol%20Building%20Full%20View.jpg?width=760", "text":"АНУ-ын Ардчилсан нам 2026 оны завсрын сонгуулиар Төлөөлөгчдийн танхимд дор хаяж 258 суудал авч, 1992 оноос хойших хамгийн том ялалтаа байгууллаа. 258 дахь суудал ням гарагт Хойд Каролина мужид Ардчилсан намын нэр дэвшигч Чак Хаббард Бүгд Найрамдах намын төлөөлөгч Виржиниа Фоксийг ялснаар баталгаажсан байна. Хаббард 48.7 хувийн санал авч, Фокс 48.6 хувийн санал авсан бөгөөд Ассошиэйтед Пресс агентлаг санал тоололтын 99 хувьтай үед уралдааныг зарласан юм.\n\nАрдчилсан нам одоогийн байдлаар 44 суудал нэмж авсан нь 2018 онд Дональд Трампын анхны завсрын сонгуулиар авсан 40 суудлаас дөрвөөр илүү байна. Бүгд Найрамдах нам дор хаяж 173 суудалтай үлдэх бөгөөд Теннесси, Миннесота, Луизиана мужуудад дөрвөн суудлын үр дүн хараахан гараагүй байна. 435 суудалтай танхимд олонх болохын тулд 218 суудал шаардлагатай.\n\nАрдчилсан нам 2027 оны нэгдүгээр сараас эхлэн Төлөөлөгчдийн танхим болон Сенатын аль алинд нь олонх болох бөгөөд Цагаан ордонд Бүгд Найрамдах намын Ерөнхийлөгч сууж байгаа тул засаглал хуваагдах юм. Тус нам сонгогчдын дэмжлэгтэйгээр засаглах өргөн боломжтой болохын зэрэгцээ сонгуулийн амлалтаа биелүүлэх дарамттай тулгарч байна.\n\nАссошиэйтед Пресс агентлагийн мэдээлснээр Ардчилсан намын Төлөөлөгчдийн танхимын нийт саналаар 14 онооны ялалт нь 1974 оноос хойших завсрын сонгуулийн хамгийн том ялалт болж байна. Сонгогчдын сэтгэл ханамжгүй байдал нь үнийн өсөлт, Ирантай холбоотой дайн, авлигын асуудлаас үүдэлтэй гэж ажиглагчид үзэж байна.", "textEn":"The Democratic Party has won at least 258 seats in the US House of Representatives in the 2026 midterm elections, its largest majority since 1992. The 258th seat was secured on Sunday when Democrat Chuck Hubbard defeated Republican Representative Virginia Foxx in North Carolina. Hubbard won 48.7 percent of the vote to Foxx's 48.6 percent, and the Associated Press called the race with 99 percent of votes counted.\n\nDemocrats have gained 44 seats so far, four more than the 40 they picked up in Donald Trump's first midterm in 2018. Republicans will hold at least 173 seats, with four races in Tennessee, Minnesota and Louisiana still uncalled. A majority in the 435-seat House requires 218 seats.\n\nFrom January 2027, Democrats will control both the House and the Senate, while a Republican president sits in the White House, creating divided government. The party gains broad scope to govern with voters' backing, but also faces pressure to deliver on its campaign promises.\n\nAccording to the Associated Press, the Democrats' 14-point victory in the House popular vote is the largest in any midterm since 1974. Observers attribute voter dissatisfaction to rising prices, the war involving Iran and concerns about corruption."},
  {"id":11, "cat":"delhii", "title":"Оросын цохилтонд Киев мужид 6 хүн амиа алдаж, орон сууцны барилга нуржээ", "titleEn":"Russian strikes kill 6 in Kyiv region as apartment block collapses", "time":"1 цаг", "timeEn":"1 hour", "img":"https://commons.wikimedia.org/wiki/Special:FilePath/80-391-9007%20Kyiv%20St.Michael%27s%20Golden-Domed%20Monastery%20RB%2018.jpg?width=760", "text":"Оросын цохилтын улмаас Киев мужид 6 хүн амиа алдсан гэж Украины албаныхан мэдээллээ. Киев хотын ойролцоох орон сууцны барилгад Оросын нисгэгчгүй нисэх төхөөрөмж тусч, аврах багийнхан нурангид дарагдсан хүмүүсийг хайж байна. Одоогийн байдлаар дор хаяж гурван хүн амиа алдсан нь батлагдаж, 11 хүртэлх хүн нурангид дарагдсан байж болзошгүй гэж албаныхан мэдээлж байна.\n\nАрваннэгдүгээр сарын 20-ноос 21-нд шилжих шөнө Орос Украин руу гурван баллистик пуужин, 148 нисгэгчгүй нисэх төхөөрөмж хөөргөсний 117-г нь Украины агаарын довтолгооноос хамгаалах хүчин устгасан буюу саатуулсан байна. Энэ нь Оросын Украины эсрэг хийж буй өргөн хэмжээний шөнийн довтолгооны сүүлийнх нь болж байна.\n\nМөн АНУ-ын тагнуулын дарга Оросын Ерөнхийлөгч Владимир Путинийг «Америкийн найз биш» гэж мэдэгдэж, Украины дайны талаарх Вашингтоны байр суурь хатуу хэвээр байгааг илэрхийлсэн байна. АНУ, Европын албаныхан Украины энх тайвны хүрээний талаар ойртох болсон бөгөөд Вашингтон НАТО-гийн хэв маягийн аюулгүй байдлын баталгаа гаргахыг хэлэлцэж байгаа ажээ.\n\nЭнэ сарын 19-нд Хятадын Шэньжэнь хотод АНУ, Хятад, Оросын удирдагчдын анхны гурван талт дээд хэмжээний уулзалт болж, «Энх тайвны төлөөх тунхаглал» гаргасан билээ. Гэсэн ч Украины дайныг дуусгах хэлэлцээ үргэлжилж, талуудын байр суурь зөрүүтэй хэвээр байна.", "textEn":"Russian strikes have killed six people in the Kyiv region, Ukrainian officials said. A drone struck an apartment building near Kyiv, and rescuers are searching for people buried in the rubble. At least three people are confirmed dead, and up to 11 more may still be trapped, officials said.\n\nOn the night of November 20-21, Russia launched three ballistic missiles and 148 drones at Ukraine, of which Ukrainian air defences destroyed or intercepted 117. It was the latest in Russia's large-scale overnight attacks on Ukraine.\n\nThe US intelligence chief has also said Russian President Vladimir Putin is 'not America's friend', underlining that Washington's position on the war in Ukraine remains firm. US and European officials have edged closer on a Ukraine peace framework, with Washington discussing NATO-style security guarantees.\n\nOn November 19, the leaders of the United States, China and Russia held their first trilateral summit in Shenzhen, China, issuing a 'Declaration Towards Peace'. Talks to end the war in Ukraine continue, with the parties' positions still far apart."},
  {"id":12, "cat":"delhii", "title":"Их Британи, Европын Холбоо Брекситийн дараах харилцааг бэхжүүлэх гэрээнд хүрлээ", "titleEn":"UK and EU reach deal to strengthen post-Brexit relations", "time":"2 цаг", "timeEn":"2 hours", "img":"https://commons.wikimedia.org/wiki/Special:FilePath/Big%20Ben%20at%20sunset%20-%202014-10-27%2017-30.jpg?width=760", "text":"Их Британи болон Европын Холбоо арваннэгдүгээр сарын 20-нд Брюссельд болсон Европын Холбоо-Их Британийн дээд хэмжээний уулзалтын үеэр Брекситийн дараах харилцаагаа бэхжүүлэх гэрээнд хүрлээ. Гэрээнд хүнсний худалдаа, нүүрстөрөгчийн ялгаруулалт, залуучуудын хөдөлгөөн зэрэг асуудал багтсан байна.\n\nУулзалтад Их Британийн Ерөнхий сайд Энди Бернхэм, Европын Комиссын Ерөнхийлөгч Урсула фон дер Ляйен нар оролцсон бөгөөд талууд худалдаа, уур амьсгал, иргэдийн хөдөлгөөний талаарх хамтын ажиллагааг сайжруулахаар тохирсон байна. Гэрээ нь Брекситийн дараа суларсан харилцааг сэргээхэд чиглэсэн чухал алхам гэж үзэж байна.\n\nГэсэн хэдий ч их, дээд сургуулийн сургалтын төлбөрийн талаарх маргаан шинэ арга хэмжээ хэзээ хэрэгжиж эхлэх талаар тодорхойгүй байдал үүсгэж байна. Талууд уг асуудлаар хэлэлцээгээ үргэлжлүүлэхээр тохиролцсон бөгөөд гэрээний хэрэгжилт нь цаашид анхаарал татаж байна.\n\nИх Британи 2020 онд Европын Холбооноос гарснаас хойш талуудын харилцаа хүндрэлтэй байсан бөгөөд худалдаа, хилийн хяналт, иргэдийн эрх зэрэг олон асуудал маргаан дагуулж ирсэн юм. Шинэ гэрээ нь эдгээр асуудлыг шийдвэрлэхэд чиглэсэн хамгийн сүүлийн оролдлого болж байна.", "textEn":"Britain and the European Union reached an agreement on Friday to strengthen post-Brexit relations at an EU-UK summit in Brussels on November 20. The deal covers food trade, carbon emissions and youth mobility.\n\nBritish Prime Minister Andy Burnham and European Commission President Ursula von der Leyen took part in the summit, agreeing to improve cooperation on trade, climate and the movement of people. The agreement is seen as an important step towards repairing relations strained since Brexit.\n\nA dispute over university tuition fees, however, has raised questions about when the new measures will take effect. The sides agreed to keep talking on the issue, and implementation of the deal will be closely watched.\n\nRelations between the two sides have been difficult since Britain left the European Union in 2020, with disputes over trade, border controls and citizens' rights. The new deal is the latest attempt to resolve those issues."},
  {"id":13, "cat":"delhii", "title":"Мексик АНУ-ын хамгийн эрэн сурвалжилж буй гэмт хэрэгтнүүдийн нэг «Эль Чапо Исидро»-г баривчилжээ", "titleEn":"Mexico captures 'El Chapo Isidro', one of the FBI's most wanted fugitives", "time":"2 цаг", "timeEn":"2 hours", "img":"https://commons.wikimedia.org/wiki/Special:FilePath/Mexico%20City%20Skyline%20%2832507119557%29.jpg?width=760", "text":"Мексикийн цэргийнхэн Холбооны мөрдөх товчооны хамгийн эрэн сурвалжилж буй 10 гэмт хэрэгтний нэг болох хар тамхины бүлэглэлийн толгойлогч Фаусто Исидро Меза Флорес буюу «Эль Чапо Исидро»-г баасан гарагийн шөнө Синалоа мужийн Гуасаве хотод баривчилжээ. Уг ажиллагааны үеэр гарсан буудалцаанд долоон гэмт хэрэгтэн, дөрвөн цэрэг амиа алдсан байна.\n\nМексикийн Батлан хамгаалах яамны мэдээлснээр тусгай хүчнийхэн «нууц, гэнэтийн» ажиллагаа явуулж, 44 настай Меза Флоресыг гэрт нь баривчилсан бөгөөд түүнийг Мехико хот руу шилжүүлсэн байна. Түүнтэй хамт бүлэглэлийн хоёрдугаар хүн болох үеэл Герман, санхүүгийн асуудал хариуцсан хүргэн Хосе нарын найман хүнийг баривчилжээ.\n\nМеза Флорес нь АНУ-д их хэмжээний героин, метамфетамин, кокаин, фентанил, марихуан импортолсон хэрэгт буруутгагдаж байгаа бөгөөд АНУ-ын Төрийн департамент түүнийг баривчлахад туслах мэдээлэл өгсөн хүнд 5 сая ам.долларын шагнал амлаж байсан юм. Холбооны мөрдөх товчоо түүнийг 2025 оны хоёрдугаар сард хамгийн эрэн сурвалжилж буй 10 гэмт хэрэгтний жагсаалтад оруулсан байна.\n\nТэрбээр «Эль Чапо» хочтой Хоакин Гусмантай хамаатан биш бөгөөд Белтран Лейва бүлэглэлийг удирдаж, Синалоа картелийн Майо фракцтай холбоотон болсон гэж Мексикийн албаныхан мэдээлж байна. Баривчилгаа нь Мексикийн Ерөнхийлөгч Клаудиа Шейнбаумд картелийн эсрэг тэмцлээ эрчимжүүлэхийг АНУ-ын Ерөнхийлөгч Дональд Трамп шаардаж байгаа үед гарч байгаа бөгөөд Мексик, АНУ-ын тагнуулын байгууллагууд хамтран ажилласан байна.", "textEn":"Mexican military forces have captured drug lord Fausto Isidro Meza Flores, known as 'El Chapo Isidro', one of the FBI's 10 most wanted fugitives, in the city of Guasave in Sinaloa state on Friday night. Seven suspected cartel gunmen and four soldiers were killed in the gunfight during the operation.\n\nMexico's Defence Ministry said special forces carried out a 'stealth and surprise' operation, arresting the 44-year-old Meza Flores at a house before flying him to Mexico City. Eight people were detained with him, including his cousin German, the group's second-in-command, and his brother-in-law Jose, its alleged financial operator.\n\nMeza Flores is accused of importing large quantities of heroin, methamphetamine, cocaine, fentanyl and marijuana into the United States, and the US State Department offered a 5 million dollar reward for information leading to his arrest. The FBI added him to its Ten Most Wanted Fugitives list in February 2025.\n\nHe is not related to Joaquin 'El Chapo' Guzman, Mexican authorities say, and leads the Beltran Leyva organisation, allied with the Mayos faction of the Sinaloa cartel. The arrest comes as Mexican President Claudia Sheinbaum faces pressure from US President Donald Trump to crack down on cartels, and Mexican and US intelligence agencies worked together on the operation."},
  {"id":14, "cat":"delhii", "title":"Иран цахилгаан эрчим хүчийг хязгаарлаж эхлэхээр болж, Персийн булан дахь хурцадмал байдал үргэлжилж байна", "titleEn":"Iran to ration electricity as Gulf tensions persist", "time":"2 цаг", "timeEn":"2 hours", "img":"https://commons.wikimedia.org/wiki/Special:FilePath/Tehran%20in%20a%20clean%20day.jpg?width=760", "text":"Иран арваннэгдүгээр сарын 22-наас цахилгаан эрчим хүчийг хязгаарлаж эхлэхээр болсон бөгөөд тус улсын эрчим хүчний сүлжээ АНУ, Израилийн цохилтын улмаас ихээхэн хохирсон гэж анхааруулж байна. АНУ-ын Ерөнхийлөгч Дональд Трампын дараагийн алхам — хэлэлцээ хийх үү, эсвэл дахин довтлох уу — тодорхойгүй байгаа үед цахилгаан хязгаарлалт эхэлж байгаа юм.\n\nИраны Гадаад хэргийн сайд Аббас Арагчи тус улсын цөмийн бодлогыг өөрчлөх тухай маргаан «хүчтэй логик»-той гэж мэдэгдсэн нь олон улсын анхаарлыг татаж байна. АНУ, Ираны хүчнүүд сүүлийн саруудад харилцан агаарын цохилт хийсээр байгаа бөгөөд Персийн булангийн орнууд оршин суугчдадаа болзошгүй довтолгооны талаар сэрэмжлүүлж байна.\n\nПерсийн булан дахь дайн ес дэх сардаа орж байгаа бөгөөд талуудын хооронд цэргийн ажиллагаа, хориг арга хэмжээ үргэлжилж байна. Хормузын хоолойд танкерууд руу довтолсон хэрэг явдал бүс нутгийн хурцадмал байдлыг улам нэмэгдүүлсэн бөгөөд тус хоолой нь дэлхийн газрын тосны тээврийн гол зам юм.\n\nТрамп Ирантай холбоотой шийдвэр гаргахдаа яарахгүй, 2027 он хүртэл шийдвэрээ хойшлуулж магадгүй гэж мэдэгдсэн бол Ираны Гадаад хэргийн сайд Тегеран дайныг дипломат аргаар дуусгахыг эрмэлзэж байгаа гэж хэлсэн байна. Талууд тохиролцоонд хүрэх эсэх нь тодорхойгүй хэвээр байна.", "textEn":"Iran will begin rationing electricity on November 22, with warnings that the country's power grid has been badly damaged by US and Israeli strikes. The rationing starts amid uncertainty over US President Donald Trump's next move — more talks or more attacks.\n\nIranian Foreign Minister Abbas Araqchi said arguments for changing the country's nuclear doctrine have 'strong logic', drawing international attention. US and Iranian forces have exchanged air strikes in recent months, and Gulf nations have warned residents about possible incoming attacks.\n\nThe war in the Gulf is in its ninth month, with military operations and sanctions continuing. Attacks on tankers in the Strait of Hormuz have raised regional tensions further, and the strait is a main route for world oil transport.\n\nTrump has said he is not rushing decisions on Iran and might not decide until 2027, while Iran's foreign minister said Tehran still wants a diplomatic end to the war. Whether the parties can reach an agreement remains unclear."},
  {"id":15, "cat":"sport", "title":"Сүмо: Оносато Вакамотохарүг нэмэлт барилдаанд ялж, Кюүшү башёд хоёр дахь удаагаа дараалан түрүүллээ", "titleEn":"Sumo: Onosato beats Wakamotoharu in playoff to win second straight Kyushu title", "time":"30 мин", "timeEn":"30 min", "img":"https://commons.wikimedia.org/wiki/Special:FilePath/Sumo%20wrestlers.jpg?width=760", "text":"Ёкозүна Оносато Японы Фүкүока хотод болсон мэргэжлийн сүмогийн Кюүшү башёгийн аварга болж, хоёр дахь удаагаа дараалан түрүүллээ. Тэрбээр сүүлийн өдөр буюу арваннэгдүгээр сарын 22-нд 13 даваа, 2 унаатайгаар тэргүүлэгчдийн байранд тэнцсэн Вакамотохарүтэй нэмэлт барилдаанд ялж, долоо дахь удаагаа дээд зиндааны цомыг хүртсэн юм.\n\nСүүлийн өдрийн барилдаанд Оносато ёкозүна Хошорюүг түлхэж гаргаж ялсан бол Вакамотохарү сэкиваке Атамифүжиг ялж, хоёр бөх 13-2-оор тэнцсэн байна. Нэмэлт барилдаанд Оносато Вакамотохарүг хүчтэй түлхэж, дэвжээнээс гаргасан юм. Вакамотохарү 13 ялалт байгуулсан нь түүний карьерын хамгийн сайн амжилт болж, техниктэй барилдааны шагнал хүртсэн байна.\n\nЁкозүна Хошорюү С.Бямбасүрэн 9 даваа, 5 унаатайгаар тэмцээнийг дуусгасан бөгөөд энэ нь өвдөгний мэс заслын дараа анх удаа тэмцээнийг бүрэн дуусгасан явдал болж байна. Озеки Киришима 10 даваа, 5 унаатайгаар тэмцээнийг дуусгаж, энэ онд хамгийн олон буюу 65 ялалт байгуулсан бөх боллоо. Атамифүжи онцгой амжилтын шагнал, Кинбозан, Тамаваши нар тэмцэх хүсэл эрмэлзлэлийн шагнал хүртсэн байна.\n\nОносато эхний өдөр комүсүби Ёшинофүжид ялагдсан ч хурдан сэргэж, дараа нь Атамифүжид л ялагдсан юм. Тэрбээр есдүгээр сард түрүүлснийхээ дараа дараалсан хоёр дахь түрүүгээ авч байгаа бөгөөд ялалтынхаа тоог 12-3-аас 13-2 болгон сайжруулсан байна. Дараагийн их тэмцээн 2027 оны нэгдүгээр сарын 10-24-нд Токиогийн Рёогокү Кокүгикан ордонд болно.", "textEn":"Yokozuna Onosato won the Kyushu Grand Sumo Tournament in Fukuoka, Japan, claiming his second straight championship. On the final day, November 22, he beat Wakamotoharu in a championship playoff after both finished tied at 13 wins and 2 losses, earning his seventh career top-division title.\n\nOn the final day, Onosato forced out fellow yokozuna Hoshoryu, while Wakamotoharu beat sekiwake Atamifuji, leaving the two leaders deadlocked at 13-2. In the playoff, Onosato pushed Wakamotoharu back and drove him from the ring. Wakamotoharu's 13 wins were a career best, earning him the Technique Prize.\n\nYokozuna Hoshoryu S. Byambasuren finished at 9-5, completing a tournament for the first time since knee surgery. Ozeki Kirishima finished at 10-5, ending the year with the most wins, 65. Atamifuji won the Outstanding Performance Prize, while Kinbozan and Tamawashi shared the Fighting Spirit Prize.\n\nOnosato lost on the opening day to komusubi Yoshinofuji but recovered quickly, losing only to Atamifuji after that. He improved his win total from 12-3 in September to 13-2. The next grand tournament runs from January 10 to 24, 2027, at Ryogoku Kokugikan in Tokyo."},
  {"id":16, "cat":"sport", "title":"Г.Болор-Эрдэнэ пара таеквондогийн ДАШТ-ий алтан медалийн төлөөх шигшээ тулаанд шалгарлаа", "titleEn":"G. Bolor-Erdene reaches para taekwondo world championship final", "time":"1 цаг", "timeEn":"1 hour", "img":"https://commons.wikimedia.org/wiki/Special:FilePath/Taekwondo%20tournament.jpg?width=760", "text":"БНСУ-ын Мүжү хотноо үргэлжилж буй пара таеквондогийн дэлхийн аварга шалгаруулах тэмцээнд Монголын гавьяат тамирчин Г.Болор-Эрдэнэ эрэгтэйчүүдийн 63 кг-ын жинд алтан медалийн төлөөх шигшээ тулаанд шалгарлаа. Тэрбээр эхний тулаандаа Казахстаны тамирчныг хүч, техникийн давуугаар ялж, хагас шигшээд «Парис-2024» паралимпын наадмын хүрэл медальт Мароккогийн Айюб Адоуичийг буулган авсан юм.\n\nГ.Болор-Эрдэнэ нь «Парис-2024» зуны паралимпын наадмын мөнгөн медальт, дэлхийн таван удаагийн аварга, Азийн пара наадмын хошой аварга билээ. Тэрбээр дэлхийн аваргын зургаа дахь алтан медалийнхаа төлөө тулалдах гэж байгаа бөгөөд Монголын пара таеквондогийн түүхэн дэх хамгийн нэр хүндтэй тамирчдын нэг юм.\n\nТэмцээний өмнөх өдөр хөдөлмөрийн баатар У.Сүрэнжав эмэгтэйчүүдийн K44 ангиллын 52 кг-ын жинд хүрэл медаль хүртэж, Монголын багийн анхны медалийг авчирсан билээ. Өнөөдөр эрэгтэйчүүдийн 70 кг-ын жинд олон улсын хэмжээний мастер Б.Шинэбаяр дэвжээнд гарах юм.\n\nМонголын пара таеквондогийн тамирчид дэлхийн аварга шалгаруулах тэмцээнд тогтмол амжилт гаргаж, олон улсын тавцанд өрсөлдөх чадвараа харуулж байна. Г.Болор-Эрдэний шигшээ тулааны үр дүнг Монголын спортын хорхойтнууд тэсэн ядан хүлээж байгаа юм.", "textEn":"Honoured athlete G. Bolor-Erdene has reached the gold-medal match of the men's under-63-kilogram category at the Para Taekwondo World Championships under way in Muju, South Korea. He beat an athlete from Kazakhstan in his first bout and then overcame Morocco's Ayoub Adouich, a bronze medallist from the Paris 2024 Paralympic Games, in the semi-final.\n\nBolor-Erdene is a silver medallist from the Paris 2024 Paralympic Games, a five-time world champion and a two-time Asian Para Games champion. He will now fight for his sixth world championship gold medal, and he is one of the most decorated athletes in Mongolian para taekwondo history.\n\nThe previous day, Labour Hero U. Surenjav won the bronze medal in the women's K44 under-52-kilogram category, Mongolia's first medal of the championships. Today, international master B. Shinebayar will compete in the men's under-70-kilogram category.\n\nMongolia's para taekwondo athletes regularly achieve success at world championships, showing their competitiveness on the international stage. Mongolian sports fans are eagerly awaiting the result of Bolor-Erdene's final."},
  {"id":17, "cat":"soyol", "title":"Монголын мөсөн барималчид Испанид болсон олон улсын тэмцээнд алтан медаль хүртлээ", "titleEn":"Mongolian ice sculptors win gold at international competition in Spain", "time":"2 цаг", "timeEn":"2 hours", "img":"https://commons.wikimedia.org/wiki/Special:FilePath/Ice%20sculpture%20in%20Quebec%20city%20downtown.jpg?width=760", "text":"Монголын мөсөн барималчид Ц.Мөнх-Эрдэнэ, Б.Доржнамжил нар Испанийн Мадрид хотын Торрехон де Ардос хотод болсон олон улсын мөсөн баримлын 5 дугаар тэмцээнд нэгдүгээр байр эзэлж, алтан медаль хүртлээ.\n\nМөсөн баримал нь урлагийн өвөрмөц төрөл бөгөөд уран бүтээлчид хүйтэн нөхцөлд мөсөн блокоос нарийн хийцтэй баримал урладаг. Тэмцээнд дэлхийн олон орны уран бүтээлчид оролцож, ур чадвар, бүтээлч сэтгэлгээгээрээ өрсөлдсөн байна. Монголын уран бүтээлчдийн ялалт нь тус улсын мөсөн урлагийн хөгжлийг харуулж байгаа юм.\n\nМонгол Улс өвлийн хүйтэн уур амьсгалтай орон бөгөөд мөс, цасны урлаг энд байгалийн нөхцөлтэй нягт холбоотой. Монголын уран бүтээлчид сүүлийн жилүүдэд олон улсын мөсөн баримлын тэмцээнүүдэд тогтмол оролцож, амжилт гаргаж байна.\n\nЭнэ ялалт нь Монголын соёл урлагийг олон улсад сурталчлах чухал алхам бөгөөд залуу уран бүтээлчдэд урам зориг өгөх төлөвтэй байна. Мөн энэ өдрүүдэд Монголын уран бүтээлчид Венецийн 61 дүгээр олон улсын урлагийн үзэсгэлэнд «Энтанглементс» үзэсгэлэнгээр оролцож байгаа бөгөөд үзэсгэлэн арваннэгдүгээр сарын 22-нд өндөрлөсөн юм.", "textEn":"Mongolian ice sculptors Ts. Munkh-Erdene and B. Dorjnamjil won first place and a gold medal at the 5th International Ice Sculpting Competition, held in Torrejon de Ardoz, Madrid, Spain.\n\nIce sculpting is a distinctive art form in which artists carve intricate sculptures from blocks of ice in cold conditions. Artists from many countries took part in the competition, competing on skill and creativity. The Mongolian artists' victory shows the development of ice art in their country.\n\nMongolia is a country with a cold winter climate, and the art of ice and snow is closely linked to its natural conditions. Mongolian artists have regularly taken part in international ice sculpting competitions in recent years, achieving success.\n\nThe win is an important step in promoting Mongolian culture and art internationally and is expected to inspire young artists. Mongolian artists are also currently taking part in the 61st Venice International Art Exhibition with the exhibition 'Entanglements', which closed on November 22."},
  {"id":18, "cat":"tech", "title":"«GTA VI» тоглоом эхний өдрөө 3.7 тэрбум ам.долларын орлого олж, түүхэн дээд амжилт тогтоолоо", "titleEn":"GTA VI earns $3.7 billion on its first day, setting an entertainment record", "time":"2 цаг", "timeEn":"2 hours", "img":"https://commons.wikimedia.org/wiki/Special:FilePath/Hands%20holding%20video%20game%20controller%20%2850811892858%29.jpg?width=760", "text":"«Grand Theft Auto VI» буюу «GTA VI» тоглоом худалдаанд гарсан эхний өдрөө 3.7 тэрбум ам.долларын орлого олж, энтертайнмент салбарын түүхэн дээд амжилтыг тогтоолоо. Энэ нь кино, хөгжим, тоглоомын салбарын аль алинд нь өмнө нь байгаагүй өндөр үзүүлэлт болж байна.\n\n«GTA» цуврал нь дэлхийн хамгийн алдартай, хамгийн их борлуулалттай тоглоомын цувралуудын нэг бөгөөд шинэ анги нь олон жилийн хүлээлтийн дараа гарсан юм. Тоглогчид нээлттэй ертөнцөд чөлөөтэй аялж, олон төрлийн даалгавар гүйцэтгэдэг нь цувралын онцлог бөгөөд шинэ анги нь график, тоглоомын явц, түүхийн хувьд өмнөх ангиудаасаа илүү сайжирсан гэж шүүмжлэгчид үзэж байна.\n\nТоглоомын салбар сүүлийн жилүүдэд кино урлагаас ч их орлого олж байгаа бөгөөд «GTA VI»-ийн амжилт нь уг чиг хандлагыг улам бататгаж байна. Тоглоомын компаниуд томоохон төсөлд олон жил, олон зуун сая ам.доллар зарцуулж, кино урлагийн хэмжээнд хүрсэн бүтээл туурвидаг болсон.\n\nЭхний өдрийн борлуулалтын дээд амжилт нь тоглоомын эрэлт хэрэгцээ асар их байгааг харуулж байгаа бөгөөд «GTA VI» нь энэ оны хамгийн их яригдсан соёлын үзэгдлүүдийн нэг болох төлөвтэй байна. Тоглоомын салбарын шинжээчид уг амжилт нь цаашид гарах томоохон тоглоомуудад өндөр хүлээлт үүсгэж байгаа гэж үзэж байна.", "textEn":"Grand Theft Auto VI, or GTA VI, earned 3.7 billion US dollars on its first day on sale, setting a record for the entertainment industry. It is the highest figure ever recorded across film, music and games.\n\nThe GTA series is one of the world's most popular and best-selling game franchises, and the new instalment arrived after years of anticipation. Players roam an open world and complete a wide range of missions, and critics say the new game improves on its predecessors in graphics, gameplay and story.\n\nThe games industry has earned more than cinema in recent years, and GTA VI's success reinforces that trend. Game companies now spend years and hundreds of millions of dollars on major projects, producing works on the scale of films.\n\nThe first-day sales record shows enormous demand for the game, and GTA VI is set to become one of the most talked-about cultural events of the year. Industry analysts say the success raises expectations for other major releases to come."},
  {"id":19, "cat":"oron-nutag", "title":"Ирэх долоо хоног ихэнх нутгаар цас орж, шөнөдөө 32 хэм хүрч хүйтрэнэ", "titleEn":"Snow across most of the country next week; nights down to minus 32", "time":"2 цаг", "timeEn":"2 hours", "img":"https://commons.wikimedia.org/wiki/Special:FilePath/Mong%20winter1%20-%20panoramio.jpg?width=760", "text":"Ирэх долоо хоногт ихэнх нутгаар цас орж, хүйтний эрч чангарах төлөвтэй байна гэж Цаг уур, орчны шинжилгээний газраас мэдээллээ. Өнөөдөр буюу арваннэгдүгээр сарын 23-нд Сэлэнгийн зүүн, Хэнтийн хойд, Дорнодын зүүн сумдын нутгаар 0.1-2.0 миллиметр цас орж, зөөлөн цасан шуурга шуурах төлөвтэй байна.\n\nАрваннэгдүгээр сарын 25-нд Баян-Өлгий, Увс, Завханы зарим сумд, Хөвсгөлийн баруун сумдын нутгаар, 26-нд Завхан, Хөвсгөл, Архангай, Хэнтий, Сүхбаатар, Дорнодын зарим сумд, Булган, Төв, Сэлэнгийн ихэнх, Дундговь, Дорноговийн хойд сумдын нутгаар 0.1-4.0 миллиметр цас орж, зөөлөн цасан шуурга шуурна. Салхи ихэнх хугацаанд секундэд 5-10 метр, 23-нд говь, тал, хээрийн нутгаар секундэд 14-16 метр хүрч ширүүснэ.\n\nШөнөдөө Дархадын хотгор, Завхан, Заг, Байдраг голын эх, Хүрэнбэлчир орчмоор 27-32 хэм, Алтай, Хангай, Хөвсгөл, Хэнтийн уулархаг нутаг, Идэр, Тэс, Туул, Тэрэлж голын хөндийгөөр 20-25 хэм, говийн бүс нутгийн өмнөд хэсгээр 8-13 хэм, бусад нутгаар 14-19 хэм хүйтэн байна. Өдөртөө Дархадын хотгор, Завхан, Заг, Байдраг, Хүрэнбэлчир орчим, Идэр, Тэс голын хөндийгөөр 14-19 хэм, говийн бүс нутгийн өмнөд хэсгээр 1-6 хэм, бусад нутгаар 6-11 хэм хүйтэн байх төлөвтэй байна.\n\nУлаанбаатар хот орчмоор үүлшинэ, шөнөдөө ялимгүй цас орж, өдөртөө 5-7 хэм хүйтэн байна. Малчид, иргэд, тээвэрчид хол замд гарахдаа цаг агаарын мэдээг тогтмол авч, замын нөхцөл байдлыг урьдчилан шалгахыг цаг уурын байгууллагаас анхааруулж байна. Энэ өвөл олон жилийн дунджаас 5 хэмээр хүйтэн байх төлөвтэй байгаа бөгөөд 330 сумын 290 нь зудын эрсдэлтэй гэж үнэлэгдсэн юм.", "textEn":"Snow is expected across most of the country next week, with temperatures falling sharply, the National Agency for Meteorology and Environmental Monitoring said. Today, November 23, snow of 0.1-2.0 millimetres and light blizzards are expected in eastern Selenge, northern Khentii and eastern Dornod soums.\n\nOn November 25, snow is expected in some soums of Bayan-Ulgii, Uvs and Zavkhan and western soums of Khuvsgul, and on November 26 in some soums of Zavkhan, Khuvsgul, Arkhangai, Khentii, Sukhbaatar and Dornod, most soums of Bulgan, Tuv and Selenge, and northern soums of Dundgovi and Dornogovi, with 0.1-4.0 millimetres and light blizzards. Winds will mostly reach 5-10 metres per second, rising to 14-16 metres per second on November 23 across the Gobi, steppe and field regions.\n\nOvernight, temperatures will fall to minus 27-32 degrees in the Darkhad depression, around the sources of the Zavkhan, Zag and Baidrag rivers and Khurenbelchir, minus 20-25 in the Altai, Khangai, Khuvsgul and Khentii mountains and the valleys of the Ider, Tes, Tuul and Terelj rivers, minus 8-13 in the southern Gobi, and minus 14-19 elsewhere. Daytime temperatures will be minus 14-19 in the Darkhad depression and around the Zavkhan, Zag and Baidrag sources, minus 1-6 in the southern Gobi and minus 6-11 elsewhere.\n\nAround Ulaanbaatar it will be mostly cloudy with slight snow overnight and minus 5-7 degrees during the day. Herders, residents and drivers are urged to follow weather updates and check road conditions before long journeys. This winter is expected to be 5 degrees colder than the long-term average, and 290 of the country's 330 soums have been assessed as being at dzud risk.", "region":"dornod"},
];



function aTitle(a){ return LANG === "en" ? (a.titleEn || a.title) : a.title; }
function aTime(a){ return LANG === "en" ? (a.timeEn || a.time) : a.time; }
function aText(a){ if(a.text) return LANG === "en" ? (a.textEn || a.text) : a.text; return SAMPLE_TEXT[LANG][a.id === 1 ? "long" : "short"]; }
function aRegion(a){ return a.region ? ((REGIONS[LANG] && REGIONS[LANG][a.region]) || a.region) : ""; }

// ===== Ханш · Цаг агаар (өдөр бүр шинэчлэгдэнэ; цаг агаарыг Open-Meteo-гоос шууд татна) =====
const RATES = {date:"2026-11-23", items:[{code:"USD", mnt:3607.00, chg:0}, {code:"EUR", mnt:3961.93, chg:0}, {code:"JPY", mnt:22.66, chg:0}, {code:"CNY", mnt:540.35, chg:0}, {code:"KRW", mnt:2.70, chg:0}, {code:"RUB", mnt:44.04, chg:0}, {code:"GBP", mnt:4730.40, chg:0}]};
let WEATHER = [
  {city:"Улаанбаатар", cityEn:"Ulaanbaatar", lat:47.9212, lon:106.9186, tz:"Asia/Ulaanbaatar", temp:-19, code:0},
  {city:"Токио", cityEn:"Tokyo", lat:35.6762, lon:139.6503, tz:"Asia/Tokyo", temp:4, code:0},
  {city:"Сөүл", cityEn:"Seoul", lat:37.5665, lon:126.978, tz:"Asia/Seoul", temp:2, code:1},
  {city:"Бээжин", cityEn:"Beijing", lat:39.9042, lon:116.4074, tz:"Asia/Shanghai", temp:2, code:0},
  {city:"Москва", cityEn:"Moscow", lat:55.7558, lon:37.6173, tz:"Europe/Moscow", temp:0, code:2},
];
function wIcon(code){
  if(code === 0) return "☀️";
  if(code === 1) return "🌤️";
  if(code === 2) return "⛅";
  if(code === 3) return "☁️";
  if(code === 45 || code === 48) return "🌫️";
  if(code === 51 || code === 53 || code === 55 || code === 80) return "🌦️";
  if(code === 56 || code === 57 || code === 61 || code === 63 || code === 65 || code === 66 || code === 67 || code === 81 || code === 82) return "🌧️";
  if(code === 71 || code === 73 || code === 75 || code === 77 || code === 85 || code === 86) return "❄️";
  if(code >= 95) return "⛈️";
  return "🌡️";
}
function fmtRate(v){
  if(v >= 100) return Math.round(v).toLocaleString("en-US");
  return v.toFixed(2);
}
function renderData(){
  const parts = [];
  RATES.items.forEach(r=>{
    let arrow = "";
    if(r.chg > 0) arrow = ' <span class="up">▲</span>';
    else if(r.chg < 0) arrow = ' <span class="down">▼</span>';
    parts.push(`<span class="tk"><b>${r.code}</b> ${fmtRate(r.mnt)}₮${arrow}</span>`);
  });
  WEATHER.forEach(w=>{
    const name = LANG === "en" ? w.cityEn : w.city;
    const t = w.temp > 0 ? "+" + w.temp : "" + w.temp;
    parts.push(`<span class="tk">${wIcon(w.code)} ${name} ${t}°C</span>`);
  });
  const html = parts.join('<span style="color:#666">•</span>');
  const track = document.getElementById("tickerTrack");
  if(track) track.innerHTML = html + '<span style="color:#666">•</span>' + html + '<span style="color:#666">•</span>';
  const usd = RATES.items.find(r=>r.code === "USD");
  const ue = document.getElementById("usdText");
  if(ue && usd) ue.textContent = "USD: " + fmtRate(usd.mnt) + "₮";
  const wt = document.getElementById("weatherText");
  const ub = WEATHER[0];
  if(wt && ub) wt.textContent = wIcon(ub.code) + " " + (LANG === "en" ? ub.cityEn : ub.city) + " " + (ub.temp > 0 ? "+" + ub.temp : ub.temp) + "°C";
}
function refreshWeather(){
  WEATHER.forEach((w, idx)=>{
    const url = "https://api.open-meteo.com/v1/forecast?latitude=" + w.lat + "&longitude=" + w.lon + "&current=temperature_2m%2Cweather_code&timezone=" + encodeURIComponent(w.tz);
    fetch(url).then(r=>r.json()).then(d=>{
      if(d && d.current){ WEATHER[idx].temp = Math.round(d.current.temperature_2m); WEATHER[idx].code = d.current.weather_code; renderData(); }
    }).catch(()=>{});
  });
}

